MATCH (p:Player)-[pf:playsFor {name: 'Los Angeles Clippers'}]-(t:Team)
WITH p, COUNT(DISTINCT pf) AS play_count
CALL apoc.periodic.iterate(
  "MATCH (a:Award)<-[ra:receivesAward]-(p:Player) RETURN p.name AS player_name, ra.year AS award_year ORDER BY player_name, award_year",
  "RETURN player_name, COUNT(award_year) AS award_count",
  {batchSize: 100}
)
YIELD batch, total
RETURN p.name AS player_name, play_count, total AS award_count
ORDER BY player_name;

